from primitive_api import (
    query_symbolic_state,
    validate_program_step,
    execute_program_step,
    list_executable_actions,
    check_activity_success,
    write_evidence,
)

before = {
    "status": check_activity_success(),
    "television": query_symbolic_state("television"),
}
action = "[WALK] <television> (278)"
validation = validate_program_step(action)
result = execute_program_step(action) if validation.get("valid_action") else None
after = {
    "result": result,
    "status": check_activity_success(),
    "television_executable": list_executable_actions("television", limit=30),
}
write_evidence("walk_to_television_278", {
    "before": before,
    "action": action,
    "validation": validation,
    "after": after,
})
print({
    "action": action,
    "validation": validation,
    "result": result,
    "status": after["status"],
    "next_tv_actions": after["television_executable"],
})
